<script setup lang="ts">import type { BlindBox } from '../data';defineProps<{box:BlindBox}>();defineEmits<{draw:[box:BlindBox,count:number]}>()</script>
<template><article class="box-card card"><RouterLink :to="`/blind-boxes/${box.id}`" class="box-image"><span :class="['badge',box.remaining===0?'sold':'']">{{box.badge}}</span><img :src="box.image" :alt="box.name" loading="lazy"></RouterLink><div class="box-body"><div class="tags"><span v-for="tag in box.tags.slice(0,3)" :key="tag" class="pill">{{tag}}</span></div><RouterLink :to="`/blind-boxes/${box.id}`"><h3>{{box.name}}</h3><p>{{box.subtitle}}</p></RouterLink><div class="price"><small>单次抽取</small><strong>{{box.price.toLocaleString()}} <em>OK Coin</em></strong></div><div class="stock"><div><span>剩余库存</span><b>{{box.remaining}} / {{box.total}}</b></div><div class="progress"><i :style="{width:`${box.remaining/box.total*100}%`}"></i></div></div><div class="actions"><button class="btn btn-outline" :disabled="!box.remaining" @click="$emit('draw',box,1)">单抽</button><button class="btn btn-primary" :disabled="box.remaining<10" @click="$emit('draw',box,10)">十连抽</button></div><small v-if="box.remaining>0&&box.remaining<10" class="disabled-reason">库存不足 10，暂不可十连抽</small></div></article></template>
